// Full JSON backup and restore (user data only).
// Rebuildable caches (occurrence_cache, alarms_index) are skipped and
// regenerated by their owners. Attachment file bytes are not included;
// attachment rows are, so missing files are reported, not crashed on.
// External input is validated: wrong shapes throw BackupFormatException.
import 'dart:convert';

import 'package:drift/drift.dart';

import '../../../data/drift/app_database.dart';

class BackupFormatException implements Exception {
  BackupFormatException(this.message);
  final String message;
  @override
  String toString() => 'BackupFormatException: $message';
}

class BackupService {
  BackupService(this._db);
  final AppDatabase _db;

  static const int version = 1;

  /// All user tables as JSON-ready maps.
  Future<Map<String, dynamic>> exportJson() async {
    Future<List<Map<String, dynamic>>> jsonOf<T extends Table, D>(
      TableInfo<T, D> table,
    ) async {
      final rows = await _db.select(table).get();
      return [for (final r in rows) (r as dynamic).toJson()];
    }

    return {
      'version': version,
      'exportedAt': DateTime.now().toUtc().millisecondsSinceEpoch,
      'tables': {
        'calendars': await jsonOf(_db.calendars),
        'events': await jsonOf(_db.events),
        'event_attendees': await jsonOf(_db.eventAttendees),
        'task_lists': await jsonOf(_db.taskLists),
        'tasks': await jsonOf(_db.tasks),
        'task_tags': await jsonOf(_db.taskTags),
        'smart_lists': await jsonOf(_db.smartLists),
        'tags': await jsonOf(_db.tags),
        'tag_defaults': await jsonOf(_db.tagDefaults),
        'habit_sections': await jsonOf(_db.habitSections),
        'habits': await jsonOf(_db.habits),
        'habit_logs': await jsonOf(_db.habitLogs),
        'countdowns': await jsonOf(_db.countdowns),
        'focus_sessions': await jsonOf(_db.focusSessions),
        'folders': await jsonOf(_db.folders),
        'notes': await jsonOf(_db.notes),
        'note_links': await jsonOf(_db.noteLinks),
        'attachments': await jsonOf(_db.attachments),
        'outbox': await jsonOf(_db.outbox),
        'sync_state': await jsonOf(_db.syncState),
        'drafts': await jsonOf(_db.drafts),
      },
    };
  }

  String encode(Map<String, dynamic> backup) => jsonEncode(backup);

  Map<String, dynamic> decode(String raw) {
    final parsed = jsonDecode(raw);
    if (parsed is! Map<String, dynamic>) {
      throw BackupFormatException('Top level must be an object.');
    }
    return parsed;
  }

  /// Destroys local rows and replaces them with [backup]. Validates first.
  Future<void> restoreJson(Map<String, dynamic> backup) async {
    if (backup['version'] != version) {
      throw BackupFormatException(
        'Unsupported backup version ${backup['version']}.',
      );
    }
    final tables = backup['tables'];
    if (tables is! Map) {
      throw BackupFormatException('Missing tables object.');
    }
    final rowsOf = <String, List<Map<String, dynamic>>>{};
    for (final e in tables.entries) {
      final list = e.value;
      if (list is! List) {
        throw BackupFormatException('Table ${e.key} must be a list.');
      }
      rowsOf[e.key as String] = [
        for (var i = 0; i < list.length; i++) _row(e.key as String, i, list[i]),
      ];
    }
    await _db.transaction(() async {
      // Children before parents (foreign keys are on).
      final clearOrder = <TableInfo<Table, dynamic>>[
        _db.eventAttendees,
        _db.taskTags,
        _db.noteLinks,
        _db.tasks,
        _db.events,
        _db.notes,
        _db.habitLogs,
        _db.calendars,
        _db.taskLists,
        _db.smartLists,
        _db.tags,
        _db.tagDefaults,
        _db.folders,
        _db.habitSections,
        _db.habits,
        _db.countdowns,
        _db.focusSessions,
        _db.attachments,
        _db.outbox,
        _db.syncState,
        _db.drafts,
      ];
      for (final t in clearOrder) {
        await _db.delete(t).go();
      }
      // Parents before children.
      await _insertAll(_db.calendars, rowsOf['calendars'], _calendarOf);
      await _insertAll(_db.taskLists, rowsOf['task_lists'], _taskListOf);
      await _insertAll(_db.folders, rowsOf['folders'], _folderOf);
      await _insertAll(_db.tags, rowsOf['tags'], _tagOf);
      await _insertAll(
        _db.habitSections,
        rowsOf['habit_sections'],
        _habitSectionOf,
      );
      await _insertAll(_db.smartLists, rowsOf['smart_lists'], _smartListOf);
      await _insertAll(_db.tagDefaults, rowsOf['tag_defaults'], _tagDefaultOf);
      await _insertAll(_db.events, rowsOf['events'], _eventOf);
      await _insertAll(
        _db.eventAttendees,
        rowsOf['event_attendees'],
        _attendeeOf,
      );
      await _insertAll(_db.tasks, rowsOf['tasks'], _taskOf);
      await _insertAll(_db.taskTags, rowsOf['task_tags'], _taskTagOf);
      await _insertAll(_db.notes, rowsOf['notes'], _noteOf);
      await _insertAll(_db.noteLinks, rowsOf['note_links'], _noteLinkOf);
      await _insertAll(_db.habits, rowsOf['habits'], _habitOf);
      await _insertAll(_db.habitLogs, rowsOf['habit_logs'], _habitLogOf);
      await _insertAll(_db.countdowns, rowsOf['countdowns'], _countdownOf);
      await _insertAll(_db.focusSessions, rowsOf['focus_sessions'], _focusOf);
      await _insertAll(_db.attachments, rowsOf['attachments'], _attachmentOf);
      await _insertAll(_db.outbox, rowsOf['outbox'], _outboxOf);
      await _insertAll(_db.syncState, rowsOf['sync_state'], _syncStateOf);
      await _insertAll(_db.drafts, rowsOf['drafts'], _draftOf);
    });
  }

  Future<void> _insertAll<T extends Table, D>(
    TableInfo<T, D> table,
    List<Map<String, dynamic>>? rows,
    Insertable<D> Function(Map<String, dynamic> m) build,
  ) async {
    if (rows == null) return;
    for (final m in rows) {
      await _db.into(table).insert(build(m));
    }
  }

  Map<String, dynamic> _row(String table, int i, dynamic v) {
    if (v is! Map) throw BackupFormatException('Row $i of $table malformed.');
    return Map<String, dynamic>.from(v);
  }

  // Typed readers: JSON numbers may decode as int or double; bools may be
  // stored as 0/1 by hand-written backups.
  String _reqStr(Map<String, dynamic> m, String key) {
    final v = m[key];
    if (v is! String) throw BackupFormatException('Field $key must be text.');
    return v;
  }

  String? _optStr(Map<String, dynamic> m, String key) {
    final v = m[key];
    if (v == null) return null;
    if (v is! String) throw BackupFormatException('Field $key must be text.');
    return v;
  }

  int _reqInt(Map<String, dynamic> m, String key) {
    final v = m[key];
    if (v is int) return v;
    throw BackupFormatException('Field $key must be an integer.');
  }

  int? _optInt(Map<String, dynamic> m, String key) {
    final v = m[key];
    if (v == null) return null;
    if (v is int) return v;
    throw BackupFormatException('Field $key must be an integer.');
  }

  double? _optDouble(Map<String, dynamic> m, String key) {
    final v = m[key];
    if (v == null) return null;
    if (v is num) return v.toDouble();
    throw BackupFormatException('Field $key must be a number.');
  }

  bool _reqBool(Map<String, dynamic> m, String key, {bool fallback = false}) {
    final v = m[key];
    if (v == null) return fallback;
    if (v is bool) return v;
    if (v is int) return v != 0;
    throw BackupFormatException('Field $key must be true/false.');
  }

  CalendarsCompanion _calendarOf(Map<String, dynamic> m) =>
